solution:
class OldAPI {
  getData() { return { first: 'John', last: 'Doe' }; }
}
class NewAPI {
  constructor(old) { this.old = old; }
  getFullName() {
    const d = this.old.getData();
    return d.first + ' ' + d.last;
  }
}
console.log(new NewAPI(new OldAPI()).getFullName());
